420	    /// Hydrates a single NetworkTimeEntry by fetching projects/tasks/clients
421	    /// only when the entry references a project_id or task_id.
422	    async fn hydrate_single_network_entry(&self, network_entry: NetworkTimeEntry) -> TimeEntry {
423	        let has_project = network_entry.project_id.is_some();
424	        let has_task = network_entry.task_id.is_some();
425	
426	        if !has_project && !has_task {
427	            return TimeEntry {
428	                id: network_entry.id,
429	                description: network_entry.description,
430	                start: network_entry.start,
431	                stop: network_entry.stop,
432	                duration: network_entry.duration,
433	                billable: network_entry.billable,
434	                workspace_id: network_entry.workspace_id,
435	                tags: network_entry.tags.unwrap_or_default(),
436	                project: None,
437	                task: None,
438	                ..Default::default()
439	            };
440	        }
441	
442	        let (network_projects, network_tasks, network_clients) = tokio::join!(
443	            self.get_projects(),
444	            async {
445	                if has_task {
446	                    self.get_tasks().await
447	                } else {
448	                    Ok(Vec::new())
449	                }
450	            },
451	            self.get_clients(),
452	        );
453	
454	        let clients = Self::map_clients(network_clients.unwrap_or_default());
455	        let projects = Self::map_projects(network_projects.unwrap_or_default(), &clients);
456	        let tasks = Self::map_tasks(network_tasks.unwrap_or_default(), &projects);
457	
458	        Self::map_network_time_entry(network_entry, &projects, &tasks)
459	    }
