508	    pub fn from_credentials(
509	        credentials: credentials::Credentials,
510	        proxy: Option<String>,
511	    ) -> ResultWithDefaultError<V9ApiClient> {
512	        let cache_namespace = cache_namespace_for_token(&credentials.api_token);
513	        let auth_string = credentials.api_token + ":api_token";
514	        let header_content =
515	            "Basic ".to_string() + general_purpose::STANDARD.encode(auth_string).as_str();
516	        let mut headers = header::HeaderMap::new();
517	        let auth_header =
518	            header::HeaderValue::from_str(header_content.as_str()).expect("Invalid header value");
519	        headers.insert(header::AUTHORIZATION, auth_header);
520	
521	        // Set an explicit User-Agent. Cloudflare Bot Fight Mode (enabled by default
522	        // on Free plans) returns HTTP 403 "managed challenge" for requests with an
523	        // empty UA, which otherwise takes down any self-hosted OpenToggl instance
524	        // sitting behind Cloudflare (including our CI target track.opentoggl.com).
525	        let user_agent = concat!("toggl-cli/", env!("CARGO_PKG_VERSION"));
526	        let base_client = Client::builder()
527	            .default_headers(headers)
528	            .user_agent(user_agent);
529	        let http_client = {
530	            if let Some(proxy) = proxy {
531	                base_client.proxy(reqwest::Proxy::all(proxy).expect("Invalid proxy"))
532	            } else {
533	                base_client
534	            }
535	        }
536	        .build()
537	        .expect("Couldn't build a http client");
538	        let is_official_service = credentials.api_url.is_none();
539	        let base_url = credentials
540	            .api_url
541	            .unwrap_or_else(|| constants::TOGGL_API_URL_OFFICIAL.to_string());
542	        let api_client = Self {
543	            http_client,
544	            base_url,
545	            is_official_service,
546	            cache_namespace,
547	            last_time_entry_mutation: std::sync::Arc::new(std::sync::Mutex::new(None)),
548	            last_related_mutation: std::sync::Arc::new(std::sync::Mutex::new(
549	                std::collections::HashMap::new(),
550	            )),
551	        };
552	        Ok(api_client)
553	    }
