555	    async fn get<T: de::DeserializeOwned>(&self, url: String) -> ResultWithDefaultError<T> {
556	        if let Some(cached_body) = self.read_cached_body(&url) {
557	            return deserialize_response_body(&cached_body);
558	        }
559	
560	        let response = self.http_client.get(url.clone()).send().await;
561	        let result = match response {
562	            Err(error) => Err(Box::new(ApiError::NetworkWithMessage(error.to_string()))
563	                as Box<dyn std::error::Error + Send>),
564	            Ok(response) => {
565	                let status = response.status();
566	                let body = response.text().await.map_err(|error| {
567	                    Box::new(ApiError::NetworkWithMessage(error.to_string()))
568	                        as Box<dyn std::error::Error + Send>
569	                })?;
570	
571	                if !status.is_success() {
572	                    Err(Box::new(api_error_for_http_status(
573	                        status,
574	                        &body,
575	                        self.is_official_service,
576	                    )) as Box<dyn std::error::Error + Send>)
577	                } else {
578	                    self.write_cached_body(&url, &body);
579	                    deserialize_response_body(&body)
580	                }
581	            }
582	        };
583	
584	        result
585	    }
