587	    fn read_cached_body(&self, url: &str) -> Option<String> {
588	        if !is_cacheable_get_url(url) || is_http_cache_disabled() {
589	            return None;
590	        }
591	
592	        let now = chrono::Utc::now().timestamp();
593	
594	        // Skip cache for time entry requests if there was a recent mutation
595	        if url.contains("/me/time_entries") {
596	            if let Ok(last_mutation) = self.last_time_entry_mutation.lock() {
597	                if let Some(last_mutation_time) = *last_mutation {
598	                    if now - last_mutation_time < MUTATION_BYPASS_WINDOW_SECONDS {
599	                        return None;
600	                    }
601	                }
602	            }
603	        }
604	
605	        // Skip cache for related endpoints if there was a recent mutation affecting them
606	        if let Ok(related_mutations) = self.last_related_mutation.lock() {
607	            for (endpoint_pattern, last_mutation_time) in related_mutations.iter() {
608	                if url.contains(endpoint_pattern)
609	                    && now - last_mutation_time < MUTATION_BYPASS_WINDOW_SECONDS
610	                {
611	                    return None;
612	                }
613	            }
614	        }
615	
616	        // Cross-process bypass: a *previous* CLI invocation may have just mutated one of
617	        // these endpoints. Its in-memory state is gone, but it left a breadcrumb in
618	        // `last_mutations.json`. Consulting it lets poll loops (`wait_for_entry_on_day`
619	        // etc. in live tests) actually see fresh server state after the mutation
620	        // completes and Toggl's own eventual-consistency window settles.
621	        let journal = self.load_recent_mutation_journal(now);
622	        for (endpoint_pattern, last_mutation_time) in journal.iter() {
623	            if url.contains(endpoint_pattern)
624	                && now - last_mutation_time < MUTATION_BYPASS_WINDOW_SECONDS
625	            {
626	                return None;
627	            }
628	        }
629	
630	        let cache_path = self.cache_file_path(url)?;
631	        let contents = fs::read_to_string(cache_path).ok()?;
632	        let cached = serde_json::from_str::<CachedResponse>(&contents).ok()?;
633	        let age = chrono::Utc::now().timestamp() - cached.fetched_at_epoch_seconds;
634	        if age < 0 || age > cache_ttl_seconds_for_url(url) {
635	            return None;
636	        }
637	        Some(cached.body)
638	    }
639	
640	    fn write_cached_body(&self, url: &str, body: &str) {
641	        if !is_cacheable_get_url(url) || is_http_cache_disabled() {
642	            return;
643	        }
644	
645	        let Some(cache_path) = self.cache_file_path(url) else {
646	            return;
647	        };
648	        let Some(cache_dir) = cache_path.parent() else {
649	            return;
650	        };
651	        if fs::create_dir_all(cache_dir).is_err() {
652	            return;
653	        }
654	
655	        let cached = CachedResponse {
656	            fetched_at_epoch_seconds: chrono::Utc::now().timestamp(),
657	            url: Some(url.to_string()),
658	            body: body.to_string(),
659	        };
660	        let Ok(serialized) = serde_json::to_string(&cached) else {
661	            return;
662	        };
663	        let _ = fs::write(cache_path, serialized);
664	    }
