666	    fn cache_file_path(&self, url: &str) -> Option<PathBuf> {
667	        cache_root_dir().map(|root| {
668	            root.join(&self.cache_namespace)
669	                .join(format!("{}.json", stable_hash(url)))
670	        })
671	    }
