178	/// Like `parse_datetime_input`, but time-only values (HH:MM, HH:MM:SS) are
179	/// interpreted relative to `reference_date` instead of today.
180	pub fn parse_datetime_input_with_reference(
181	    input: &str,
182	    reference_date: NaiveDate,
183	) -> ResultWithDefaultError<DateTime<Utc>> {
184	    let value = input.trim();
185	
186	    // Time-only formats: use reference_date instead of today
187	    let time_formats = ["%H:%M:%S", "%H:%M"];
188	    for format in time_formats {
189	        if let Ok(time) = NaiveTime::parse_from_str(value, format) {
190	            let naive = NaiveDateTime::new(reference_date, time);
191	            return match Local.from_local_datetime(&naive) {
192	                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
193	                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
194	            };
195	        }
196	    }
197	
198	    // Fall back to the standard parser for all other formats
199	    parse_datetime_input(input)
200	}
