247	fn normalize_time_entry_list_filter(input: &str, is_until: bool) -> ResultWithDefaultError<String> {
248	    let value = input.trim();
249	    if let Ok(date) = NaiveDate::parse_from_str(value, "%Y-%m-%d") {
250	        let boundary_date = if is_until {
251	            match date.succ_opt() {
252	                Some(next_date) => next_date,
253	                None => return Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
254	            }
255	        } else {
256	            date
257	        };
258	        let naive = match boundary_date.and_hms_opt(0, 0, 0) {
259	            Some(naive) => naive,
260	            None => return Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
261	        };
262	        // Convert local time to UTC for API, ensuring proper RFC3339 format
263	        return match Local.from_local_datetime(&naive) {
264	            LocalResult::Single(local_dt) => {
265	                let utc_dt = local_dt.with_timezone(&Utc);
266	                Ok(utc_dt.format("%Y-%m-%dT%H:%M:%SZ").to_string())
267	            }
268	            LocalResult::None => {
269	                // Handle DST gaps by using UTC directly
270	                let utc_dt = Utc.from_utc_datetime(&naive);
271	                Ok(utc_dt.format("%Y-%m-%dT%H:%M:%SZ").to_string())
272	            }
273	            LocalResult::Ambiguous(dt1, _dt2) => {
274	                // Handle DST overlaps by using the first option
275	                let utc_dt = dt1.with_timezone(&Utc);
276	                Ok(utc_dt.format("%Y-%m-%dT%H:%M:%SZ").to_string())
277	            }
278	        };
279	    }
280	
281	    Ok(parse_datetime_input(value)?
282	        .format("%Y-%m-%dT%H:%M:%SZ")
283	        .to_string())
284	}
