353	impl std::fmt::Display for TimeEntry {
354	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
355	        let local_start: DateTime<Local> = self.start.with_timezone(&Local);
356	        let time_str = match self.stop {
357	            Some(stop) => {
358	                let local_stop: DateTime<Local> = stop.with_timezone(&Local);
359	                let cross_day = local_stop.date_naive() != local_start.date_naive();
360	                if cross_day {
361	                    format!(
362	                        "{} ~ {}",
363	                        local_start.format("%Y-%m-%d %H:%M"),
364	                        local_stop.format("%m-%d %H:%M")
365	                    )
366	                } else {
367	                    format!(
368	                        "{}~{}",
369	                        local_start.format("%Y-%m-%d %H:%M"),
370	                        local_stop.format("%H:%M")
371	                    )
372	                }
373	            }
374	            None => format!("{}~…", local_start.format("%Y-%m-%d %H:%M")),
375	        };
376	        let summary = format!(
377	            //{id} {date HH:MM–HH:MM} {$/space} [{duration}]{running indicator/space} – {description}{@project} {#tags}
378	            "{} {} {} [{}]{} –  {}{} {}",
379	            self.id,
380	            time_str,
381	            if self.billable {
382	                "$".green().bold().to_string()
383	            } else {
384	                " ".to_string()
385	            },
386	            if self.is_running() {
387	                self.get_duration_hmmss().green().bold()
388	            } else {
389	                self.get_duration_hmmss().normal()
390	            },
391	            if self.is_running() { "*" } else { " " },
392	            self.get_description().replace('\n', " "),
393	            match self.project.clone() {
394	                Some(p) => format!(" @{p}"),
395	                None => "".to_string(),
396	            },
397	            if self.tags.is_empty() {
398	                "".to_string()
399	            } else {
400	                format!("#{}", self.get_display_tags().italic())
401	            }
402	        );
403	        write!(f, "{summary}")
404	    }
405	}
