101	            let mut body = json!({
102	                "start_date": since,
103	                "end_date": until,
104	            });
105	            if let Some(ref g) = group_by {
106	                body["grouping"] = Value::String(g.clone());
107	            }
108	            if let Some(ref sg) = sub_group_by {
109	                body["sub_grouping"] = Value::String(sg.clone());
