117	                    serde_json::to_string(&result).expect("failed to serialize report to JSON")
118	                );
119	            } else {
120	                print_summary_report(&result, &since, &until);
121	            }
122	        }
123	        ReportAction::Detailed {
124	            since,
125	            until,
126	            json,
127	            number,
128	            order_by,
129	            order_dir,
130	        } => {
131	            let (since, until) = resolve_report_dates(since, until)?;
132	            let mut body = json!({
133	                "start_date": since,
134	                "end_date": until,
135	            });
