152	                );
153	            } else {
154	                print_detailed_report(&result, &since, &until);
155	            }
156	        }
157	        ReportAction::Weekly { since, until, json } => {
158	            let (since, until) = resolve_report_dates(since, until)?;
159	            let body = json!({
160	                "start_date": since,
161	                "end_date": until,
