192	fn print_summary_report(data: &Value, since: &str, until: &str) {
193	    println!("{}", format!("Summary Report: {since} to {until}").bold());
194	    println!("{}", "=".repeat(50));
195	
196	    let mut grand_total: i64 = 0;
197	
198	    if let Some(groups) = extract_groups(data) {
199	        for group in groups {
200	            let group_name = group
201	                .get("names")
202	                .and_then(|n| n.as_array())
203	                .and_then(|arr| arr.first())
204	                .and_then(|v| v.as_str())
205	                .unwrap_or("(unknown)");
206	
207	            // sub_groups can be an object (keyed by user/entry ID) or an array
208	            let mut group_seconds: i64 = 0;
209	            if let Some(sg_obj) = group.get("sub_groups").and_then(|sg| sg.as_object()) {
210	                for (_key, sg) in sg_obj {
211	                    let secs = sg.get("seconds").and_then(|s| s.as_i64()).unwrap_or(0);
212	                    group_seconds += secs;
213	                }
214	            } else if let Some(sg_arr) = group.get("sub_groups").and_then(|sg| sg.as_array()) {
215	                for sg in sg_arr {
216	                    let secs = sg.get("seconds").and_then(|s| s.as_i64()).unwrap_or(0);
217	                    group_seconds += secs;
218	                }
219	            }
220	
221	            grand_total += group_seconds;
222	            let duration = format_duration_hms(group_seconds);
223	
224	            let group_id = group.get("id").and_then(|v| v.as_i64()).unwrap_or(0);
225	            if group_id > 0 {
226	                println!("  {} {}", duration.green(), group_name);
227	            } else {
228	                println!("  {} {}", duration.green(), group_name.dimmed());
229	            }
230	        }
231	    }
232	
233	    // Also check for totals in the response
234	    if let Some(totals_seconds) = data
235	        .get("totals")
236	        .and_then(|t| t.get("seconds"))
237	        .and_then(|s| s.as_i64())
238	    {
239	        if grand_total == 0 {
240	            grand_total = totals_seconds;
241	        }
242	    }
243	
244	    println!("{}", "-".repeat(50));
245	    println!(
246	        "  {} {}",
247	        format_duration_hms(grand_total).green().bold(),
248	        "Total".bold()
249	    );
250	}
