252	fn print_detailed_report(data: &Value, since: &str, until: &str) {
253	    println!("{}", format!("Detailed Report: {since} to {until}").bold());
254	    println!("{}", "=".repeat(70));
255	
256	    let mut total_seconds: i64 = 0;
257	    let mut entry_count: usize = 0;
258	
259	    // The response might be wrapped in "report" or be a direct array
260	    let entries: Vec<&Value> = data
261	        .get("report")
262	        .and_then(|r| r.as_array())
263	        .or_else(|| data.get("time_entries").and_then(|v| v.as_array()))
264	        .or_else(|| data.as_array())
265	        .map(|arr| arr.iter().collect())
266	        .unwrap_or_default();
267	
268	    for entry in &entries {
269	        let description = entry
270	            .get("description")
271	            .and_then(|d| d.as_str())
272	            .unwrap_or("(no description)");
273	        let project_name = entry
274	            .get("project_name")
275	            .and_then(|p| p.as_str())
276	            .unwrap_or("");
277	        let billable = entry
278	            .get("billable")
279	            .and_then(|b| b.as_bool())
280	            .unwrap_or(false);
281	
282	        // Time entries can be nested
283	        if let Some(time_entries) = entry.get("time_entries").and_then(|te| te.as_array()) {
284	            for te in time_entries {
285	                let seconds = te.get("seconds").and_then(|s| s.as_i64()).unwrap_or(0);
286	                let start = te.get("start").and_then(|s| s.as_str()).unwrap_or("");
287	
288	                total_seconds += seconds;
289	                entry_count += 1;
290	
291	                print_detailed_entry(start, seconds, billable, description, project_name);
292	            }
293	        } else {
294	            // Flat structure: seconds directly on the entry
295	            let seconds = entry.get("seconds").and_then(|s| s.as_i64()).unwrap_or(0);
296	            let start = entry.get("start").and_then(|s| s.as_str()).unwrap_or("");
297	            total_seconds += seconds;
298	            entry_count += 1;
299	
300	            print_detailed_entry(start, seconds, billable, description, project_name);
301	        }
302	    }
303	
304	    println!("{}", "-".repeat(70));
305	    println!(
306	        "  {} {} ({} entries)",
307	        format_duration_hms(total_seconds).green().bold(),
308	        "Total".bold(),
309	        entry_count,
