 38	/// Default date window for `entry search`: 1 year back to today.
 39	/// Search is a "find-that-thing-I-did-a-while-ago" tool, so the default needs to be wide.
 40	fn resolve_search_dates(
 41	    since: Option<String>,
 42	    until: Option<String>,
 43	) -> ResultWithDefaultError<(String, String)> {
 44	    let today = Local::now().date_naive();
 45	
 46	    let since_resolved = match since {
 47	        Some(s) => resolve_search_date(&s)?,
 48	        None => (today - chrono::Duration::days(365))
 49	            .format("%Y-%m-%d")
 50	            .to_string(),
 51	    };
 52	    let until_resolved = match until {
 53	        Some(u) => resolve_search_date(&u)?,
 54	        None => today.format("%Y-%m-%d").to_string(),
 55	    };
 56	
 57	    if since_resolved > until_resolved {
 58	        return Err(Box::new(ArgumentError::InvalidTimeRange(format!(
 59	            "--since ({}) is after --until ({}).",
 60	            since_resolved, until_resolved
 61	        ))));
 62	    }
 63	    Ok((since_resolved, until_resolved))
 64	}
