142	pub async fn execute(
143	    api_client: impl ApiClient,
144	    query: Option<String>,
145	    project: Option<String>,
146	    no_project: bool,
147	    tags: Option<Vec<String>>,
148	    no_tag: bool,
149	    since: Option<String>,
150	    until: Option<String>,
151	    number: Option<i64>,
152	    order_by: Option<String>,
153	    order_dir: Option<String>,
154	    json_output: bool,
155	) -> ResultWithDefaultError<()> {
156	    let user = api_client.get_user().await?;
157	    let workspace_id = user.default_workspace_id;
158	
159	    let (since, until) = resolve_search_dates(since, until)?;
160	
161	    let mut body = json!({
162	        "start_date": since,
163	        "end_date": until,
164	    });
165	
166	    if let Some(q) = query.as_ref().filter(|q| !q.is_empty()) {
167	        body["description"] = Value::String(q.clone());
168	    }
169	
170	    // Project filter: --no-project -> [null]; -p NAME|ID -> [resolved_id]
171	    if no_project {
172	        body["project_ids"] = json!([null]);
173	    } else if let Some(ref p) = project {
174	        let id = resolve_project_id(&api_client, workspace_id, p).await?;
175	        body["project_ids"] = json!([id]);
176	    }
177	
178	    // Tag filter: --no-tag -> [null]; -t NAME... -> [ids]
179	    if no_tag {
180	        body["tag_ids"] = json!([null]);
181	    } else if let Some(ref names) = tags {
182	        if !names.is_empty() {
183	            let ids = resolve_tag_ids(&api_client, workspace_id, names).await?;
184	            body["tag_ids"] = Value::Array(ids.into_iter().map(|i| json!(i)).collect());
185	        }
186	    }
187	
188	    if let Some(n) = number {
189	        body["page_size"] = json!(n);
190	    }
191	    if let Some(ref ob) = order_by {
192	        body["order_by"] = Value::String(ob.clone());
193	    }
194	    if let Some(ref od) = order_dir {
195	        body["order_dir"] = Value::String(od.clone());
196	    }
197	
198	    let result = api_client.get_detailed_report(workspace_id, body).await?;
199	
200	    if json_output {
201	        println!(
202	            "{}",
203	            serde_json::to_string(&result).expect("failed to serialize search result to JSON")
204	        );
205	    } else {
206	        print_search_result(&result, &since, &until, query.as_deref());
207	    }
208	
209	    Ok(())
210	}
