212	fn format_duration_hms(total_seconds: i64) -> String {
213	    let h = total_seconds / 3600;
214	    let m = (total_seconds % 3600) / 60;
215	    let s = total_seconds % 60;
216	    format!("{h}:{m:02}:{s:02}")
217	}
218	
219	fn print_search_result(data: &Value, since: &str, until: &str, query: Option<&str>) {
220	    let header = match query {
221	        Some(q) if !q.is_empty() => format!("Search results for \"{q}\" ({since} to {until})"),
222	        _ => format!("Search results ({since} to {until})"),
223	    };
224	    println!("{}", header.bold());
225	    println!("{}", "=".repeat(70));
226	
227	    let entries: Vec<&Value> = data
228	        .get("report")
229	        .and_then(|r| r.as_array())
230	        .or_else(|| data.get("time_entries").and_then(|v| v.as_array()))
231	        .or_else(|| data.as_array())
232	        .map(|arr| arr.iter().collect())
233	        .unwrap_or_default();
234	
235	    if entries.is_empty() {
236	        println!("{}", "No entries found.".dimmed());
237	        return;
238	    }
239	
240	    let mut total_seconds: i64 = 0;
241	    let mut entry_count: usize = 0;
242	
243	    for entry in &entries {
244	        let description = entry
245	            .get("description")
246	            .and_then(|d| d.as_str())
247	            .unwrap_or("(no description)");
248	        let project_name = entry
249	            .get("project_name")
250	            .and_then(|p| p.as_str())
251	            .unwrap_or("");
252	        let billable = entry
253	            .get("billable")
254	            .and_then(|b| b.as_bool())
255	            .unwrap_or(false);
256	
257	        if let Some(nested) = entry.get("time_entries").and_then(|te| te.as_array()) {
258	            for te in nested {
259	                let seconds = te.get("seconds").and_then(|s| s.as_i64()).unwrap_or(0);
260	                let start = te.get("start").and_then(|s| s.as_str()).unwrap_or("");
261	                let id = te.get("id").and_then(|v| v.as_i64());
262	                total_seconds += seconds;
263	                entry_count += 1;
264	                print_row(id, start, seconds, billable, description, project_name);
265	            }
266	        } else {
267	            let seconds = entry.get("seconds").and_then(|s| s.as_i64()).unwrap_or(0);
268	            let start = entry.get("start").and_then(|s| s.as_str()).unwrap_or("");
269	            let id = entry.get("id").and_then(|v| v.as_i64());
270	            total_seconds += seconds;
271	            entry_count += 1;
272	            print_row(id, start, seconds, billable, description, project_name);
273	        }
274	    }
275	
276	    println!("{}", "-".repeat(70));
277	    println!(
278	        "  {} {} ({} entries)",
279	        format_duration_hms(total_seconds).green().bold(),
280	        "Total".bold(),
281	        entry_count,
282	    );
283	}
