285	fn print_row(
286	    id: Option<i64>,
287	    start: &str,
288	    seconds: i64,
289	    billable: bool,
290	    description: &str,
291	    project_name: &str,
292	) {
293	    let duration = format_duration_hms(seconds);
294	    let billable_marker = if billable { "$" } else { " " };
295	    let project_display = if project_name.is_empty() {
296	        String::new()
297	    } else {
298	        format!(" @{}", project_name.cyan())
299	    };
300	    let date_display = if start.len() >= 10 {
301	        &start[..10]
302	    } else {
303	        start
304	    };
305	    let id_display = match id {
306	        Some(i) => format!("{i:>10} "),
307	        None => "           ".to_string(),
308	    };
309	
310	    println!(
311	        "{}{} {} [{}] {}{}",
312	        id_display.dimmed(),
313	        billable_marker.green().bold(),
314	        date_display.dimmed(),
315	        duration.green(),
316	        description,
317	        project_display,
318	    );
319	}
