  9	/// Resolve a natural language date string to YYYY-MM-DD format.
 10	/// Supports: today, yesterday, now, this_week (Monday of current week),
 11	/// last_week (Monday of last week), or a literal YYYY-MM-DD date.
 12	fn resolve_report_date(input: &str) -> ResultWithDefaultError<String> {
 13	    let value = input.trim().to_lowercase();
 14	    let today = Local::now().date_naive();
 15	
 16	    let date = match value.as_str() {
 17	        "today" | "now" => today,
 18	        "yesterday" => today.pred_opt().unwrap(),
 19	        "this_week" => {
 20	            // Monday of the current week
 21	            let days_since_monday = today.weekday().num_days_from_monday();
 22	            today - chrono::Duration::days(days_since_monday as i64)
 23	        }
 24	        "last_week" => {
 25	            let days_since_monday = today.weekday().num_days_from_monday();
 26	            today - chrono::Duration::days((days_since_monday + 7) as i64)
 27	        }
 28	        _ => {
 29	            // Try parsing as YYYY-MM-DD
 30	            match NaiveDate::parse_from_str(&value, "%Y-%m-%d") {
 31	                Ok(d) => d,
 32	                Err(_) => {
 33	                    return Err(Box::new(ArgumentError::InvalidReportDate(
 34	                        input.trim().to_string(),
 35	                    )));
 36	                }
 37	            }
 38	        }
 39	    };
 40	
 41	    Ok(date.format("%Y-%m-%d").to_string())
 42	}
