 44	/// Resolve --since and --until for report commands, applying defaults
 45	/// (since → Monday of current week, until → today) when not provided.
 46	fn resolve_report_dates(
 47	    since: Option<String>,
 48	    until: Option<String>,
 49	) -> ResultWithDefaultError<(String, String)> {
 50	    let today = Local::now().date_naive();
 51	
 52	    let since_resolved = match since {
 53	        Some(s) => resolve_report_date(&s)?,
 54	        None => {
 55	            // Default: Monday of current week
 56	            let days_since_monday = today.weekday().num_days_from_monday();
 57	            let monday = today - chrono::Duration::days(days_since_monday as i64);
 58	            monday.format("%Y-%m-%d").to_string()
 59	        }
 60	    };
 61	
 62	    let until_resolved = match until {
 63	        Some(u) => resolve_report_date(&u)?,
 64	        None => today.format("%Y-%m-%d").to_string(),
 65	    };
 66	
 67	    // Validate that since <= until
 68	    if since_resolved > until_resolved {
 69	        return Err(Box::new(ArgumentError::InvalidTimeRange(format!(
 70	            "--since ({}) is after --until ({}). Swap the values or use a valid range.",
 71	            since_resolved, until_resolved
 72	        ))));
 73	    }
 74	
 75	    Ok((since_resolved, until_resolved))
 76	}
