 18	            let days_since_monday = today.weekday().num_days_from_monday();
 19	            today - chrono::Duration::days(days_since_monday as i64)
 20	        }
 21	        "last_week" => {
 22	            let days_since_monday = today.weekday().num_days_from_monday();
 23	            today - chrono::Duration::days((days_since_monday + 7) as i64)
 24	        }
 25	        _ => match NaiveDate::parse_from_str(&value, "%Y-%m-%d") {
 26	            Ok(d) => d,
 27	            Err(_) => {
 28	                return Err(Box::new(ArgumentError::InvalidReportDate(
 29	                    input.trim().to_string(),
 30	                )));
 31	            }
 32	        },
 33	    };
 34	
 35	    Ok(date.format("%Y-%m-%d").to_string())
 36	}
