 66	/// Resolve a project name-or-ID string to a numeric ID within the given workspace.
 67	/// Mirrors the resolution pattern used elsewhere in the codebase: try exact name match
 68	/// first, then fall back to numeric ID parsing. Lists available projects on failure.
 69	async fn resolve_project_id(
 70	    api_client: &impl ApiClient,
 71	    workspace_id: i64,
 72	    name_or_id: &str,
 73	) -> ResultWithDefaultError<i64> {
 74	    let projects = api_client.get_projects_list().await?;
 75	    let in_workspace: Vec<_> = projects
 76	        .iter()
 77	        .filter(|p| p.workspace_id == workspace_id)
 78	        .collect();
 79	
 80	    if let Some(p) = in_workspace.iter().find(|p| p.name == name_or_id) {
 81	        return Ok(p.id);
 82	    }
 83	    if let Ok(id) = name_or_id.parse::<i64>() {
 84	        if in_workspace.iter().any(|p| p.id == id) {
 85	            return Ok(id);
 86	        }
 87	    }
 88	    let available: Vec<String> = in_workspace
 89	        .iter()
 90	        .map(|p| format!("  - {} (id: {})", p.name, p.id))
 91	        .collect();
 92	    let msg = if available.is_empty() {
 93	        format!("No project found with name or ID '{}'.", name_or_id)
 94	    } else {
 95	        format!(
 96	            "No project found with name or ID '{}'. Available projects:\n{}",
 97	            name_or_id,
 98	            available.join("\n")
 99	        )
100	    };
101	    Err(Box::new(ArgumentError::ResourceNotFound(msg)))
102	}
