104	/// Resolve a tag name to a numeric ID. Tags are workspace-scoped.
105	async fn resolve_tag_ids(
106	    api_client: &impl ApiClient,
107	    workspace_id: i64,
108	    names: &[String],
109	) -> ResultWithDefaultError<Vec<i64>> {
110	    let tags = api_client.get_tags(workspace_id).await?;
111	    let mut ids = Vec::with_capacity(names.len());
112	    for name in names {
113	        match tags.iter().find(|t| t.name == *name) {
114	            Some(t) => ids.push(t.id),
115	            None => {
116	                // Fall back to numeric ID
117	                if let Ok(id) = name.parse::<i64>() {
118	                    if tags.iter().any(|t| t.id == id) {
119	                        ids.push(id);
120	                        continue;
121	                    }
122	                }
123	                let available: Vec<String> =
124	                    tags.iter().map(|t| format!("  - {}", t.name)).collect();
125	                let msg = if available.is_empty() {
126	                    format!("No tag found with name '{}'.", name)
127	                } else {
128	                    format!(
129	                        "No tag found with name '{}'. Available tags:\n{}",
130	                        name,
131	                        available.join("\n")
132	                    )
133	                };
134	                return Err(Box::new(ArgumentError::ResourceNotFound(msg)));
135	            }
136	        }
137	    }
138	    Ok(ids)
139	}
