 78	fn format_duration_hms(total_seconds: i64) -> String {
 79	    let hours = total_seconds / 3600;
 80	    let minutes = (total_seconds % 3600) / 60;
 81	    let seconds = total_seconds % 60;
 82	    format!("{hours}:{minutes:02}:{seconds:02}")
 83	}
