180	/// Extract groups from various response shapes:
181	/// - `{ "report": { "groups": [...] } }` (OpenToggl)
182	/// - `{ "groups": [...] }` (official Toggl)
183	/// - `[...]` (direct array)
184	fn extract_groups(data: &Value) -> Option<&Vec<Value>> {
185	    data.get("report")
186	        .and_then(|r| r.get("groups"))
187	        .and_then(|g| g.as_array())
188	        .or_else(|| data.get("groups").and_then(|g| g.as_array()))
189	        .or_else(|| data.as_array())
190	}
