 243	    async fn get_time_entries(
 244	        &self,
 245	        since: Option<&str>,
 246	        until: Option<&str>,
 247	    ) -> ResultWithDefaultError<Vec<NetworkTimeEntry>> {
 248	        let mut url = format!("{}/me/time_entries", self.base_url);
 249	        let mut params: Vec<String> = Vec::new();
 250	        if let Some(since) = since {
 251	            params.push(format!("start_date={since}"));
 252	        }
 253	        if let Some(until) = until {
 254	            params.push(format!("end_date={until}"));
 255	        }
 256	        if !params.is_empty() {
 257	            url = format!("{}?{}", url, params.join("&"));
 258	        }
 259	        self.get::<Vec<NetworkTimeEntry>>(url).await
 260	    }
