 24	fn aggregate_entries(entries: &[TimeEntry]) -> Vec<(String, i64)> {
 25	    let mut durations = HashMap::<String, i64>::new();
 26	
 27	    for entry in entries {
 28	        if entry.duration < 0 {
 29	            continue;
 30	        }
 31	
 32	        let project_name = entry
 33	            .project
 34	            .as_ref()
 35	            .map(|project| project.name.as_str())
 36	            .unwrap_or(constants::NO_PROJECT);
 37	        *durations.entry(project_name.to_string()).or_default() += entry.duration;
 38	    }
 39	
 40	    let mut durations: Vec<_> = durations.into_iter().collect();
 41	    durations.sort_by(|(name_a, duration_a), (name_b, duration_b)| {
 42	        duration_b.cmp(duration_a).then_with(|| name_a.cmp(name_b))
 43	    });
 44	    durations
 45	}
 46	
 47	fn render_stats(entries: &[TimeEntry]) -> String {
 48	    let durations = aggregate_entries(entries);
 49	    let total_seconds: i64 = durations.iter().map(|(_, seconds)| seconds).sum();
 50	
 51	    let mut lines: Vec<String> = durations
 52	        .into_iter()
 53	        .map(|(project_name, seconds)| {
 54	            format!(
 55	                "{}  {}",
 56	                utilities::format_duration_compact(seconds),
 57	                project_name
 58	            )
 59	        })
 60	        .collect();
 61	    lines.push(format!(
 62	        "{}  Total",
 63	        utilities::format_duration_compact(total_seconds)
 64	    ));
 65	    lines.join("\n") + "\n"
 66	}
 67	
 68	fn render_stats_json(entries: &[TimeEntry]) -> String {
 69	    let durations = aggregate_entries(entries);
 70	    let total_seconds: i64 = durations.iter().map(|(_, seconds)| seconds).sum();
 71	    let groups = durations
 72	        .into_iter()
 73	        .map(|(project, seconds)| StatsGroup { project, seconds })
 74	        .collect();
 75	
 76	    serde_json::to_string(&StatsJson {
 77	        groups,
 78	        total_seconds,
 79	    })
 80	    .expect("failed to serialize stats to JSON")
 81	}
